CREATE TABLE IF NOT EXISTS cliente (idCliente INT AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(100) NOT NULL, telefone VARCHAR(30) NOT NULL, email VARCHAR(100) NOT NULL, endereco VARCHAR(200) NOT NULL);
CREATE TABLE IF NOT EXISTS usuario (idUsuario INT AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(100) NOT NULL, login VARCHAR(50) NOT NULL UNIQUE, senha VARCHAR(255) NOT NULL, tipoAcesso VARCHAR(20) NOT NULL);
